macro_rules! DefiningTy {
    () => {
        # [doc = " The \"defining type\" for this MIR. The key feature of the \"defining"] # [doc = " type\" is that it contains the information needed to derive all the"] # [doc = " universal regions that are in scope as well as the types of the"] # [doc = " inputs/output from the MIR. In general, early-bound universal"] # [doc = " regions appear free in the defining type and late-bound regions"] # [doc = " appear bound in the signature."] # [derive (Copy , Clone , Debug)] pub (crate) enum DefiningTy < 'tcx > { # [doc = " The MIR is a closure. The signature is found via"] # [doc = " `ClosureArgs::closure_sig_ty`."] Closure (DefId , GenericArgsRef < 'tcx >) , # [doc = " The MIR is a coroutine. The signature is that coroutines take"] # [doc = " no parameters and return the result of"] # [doc = " `ClosureArgs::coroutine_return_ty`."] Coroutine (DefId , GenericArgsRef < 'tcx >) , # [doc = " The MIR is a special kind of closure that returns coroutines."] # [doc = ""] # [doc = " See the documentation on `CoroutineClosureSignature` for details"] # [doc = " on how to construct the callable signature of the coroutine from"] # [doc = " its args."] CoroutineClosure (DefId , GenericArgsRef < 'tcx >) , # [doc = " The MIR is a fn item with the given `DefId` and args. The signature"] # [doc = " of the function can be bound then with the `fn_sig` query."] FnDef (DefId , GenericArgsRef < 'tcx >) , # [doc = " The MIR represents some form of constant. The signature then"] # [doc = " is that it has no inputs and a single return value, which is"] # [doc = " the value of the constant."] Const (DefId , GenericArgsRef < 'tcx >) , # [doc = " The MIR represents an inline const. The signature has no inputs and a"] # [doc = " single return value found via `InlineConstArgs::ty`."] InlineConst (DefId , GenericArgsRef < 'tcx >) , GlobalAsm (DefId) , }
    };
}

DefiningTy!()